// Inject: <span data-logo></span> gets the wordmark, <i data-icon="circular"></i> gets an icon.
document.querySelectorAll('[data-logo]').forEach(el => { el.innerHTML = SR.logo; el.setAttribute('role','img'); el.setAttribute('aria-label','Studio Rowan'); });
document.querySelectorAll('[data-icon]').forEach(el => { const s = SR.icons[el.dataset.icon]; if (s) { el.innerHTML = s; el.setAttribute('aria-hidden','true'); } });

// Review helper: ?y=<px> shifts the page up by that offset once loaded (used for static screenshots,
// where scrolling isn't captured). Fixed/sticky elements are not representative in this mode.
(function () { const y = new URLSearchParams(location.search).get('y'); if (y) addEventListener('load', () => { document.documentElement.style.overflow = 'hidden'; document.body.style.transform = 'translateY(-' + (+y) + 'px)'; }); })();
